"""Standalone live-agent comparison report with per-case outcomes."""
from html import escape
from .agent_benchmark import VARIANTS


def render_comparison(report: dict, rollouts: list[dict], gates: list[dict]) -> str:
    labels = {"no_memory": "Geen geheugen", "unvalidated_memory": "Ongetoetst geheugen", "validated_memory": "Getoetst geheugen"}
    cards = ""
    for variant in VARIANTS:
        item = report["results"]["variants"][variant]
        cards += f'<article><p>{labels[variant]}</p><strong>{item["successful"]}/{item["total"]}</strong><p>Taken werkelijk voltooid en geverifieerd</p><dl><dt>Modelaanroepen</dt><dd>{item["model_calls"]}</dd><dt>Toolacties</dt><dd>{item["tool_calls"]}</dd><dt>Kalibraties opgehaald</dt><dd>{item["calibration_reads"]}</dd><dt>Invoer- / uitvoertokens</dt><dd>{item["input_tokens"]} / {item["output_tokens"]}</dd></dl></article>'
    rows = ""
    for trial, case_id in sorted({(row["trial"], row["case_id"]) for row in rollouts}):
        selected = [next(row for row in rollouts if (row["trial"], row["case_id"], row["variant"]) == (trial, case_id, variant)) for variant in VARIANTS]
        cells = "".join(f'<td class="{ "ok" if row["grade"]["passed"] else "bad" }">{"Geslaagd" if row["grade"]["passed"] else "Mislukt"}<small>{row["model_calls"]} modelaanroepen · {row["tool_calls"]} toolacties</small></td>' for row in selected)
        different = len({row["grade"]["passed"] for row in selected}) > 1
        rows += f'<tr data-different="{str(different).lower()}"><td>{trial+1}</td><td>{escape(case_id)}<small>{escape(selected[0]["category"])}</small></td>{cells}</tr>'
    gate_rows = "".join(f'<li><strong>{escape(gate["rule"]["source"])}</strong> / trial {gate["trial"]+1}: scale {gate["rule"]["scale"]}, offset {gate["rule"]["offset"]} — {"bewaard" if gate["accepted"] else "afgewezen"}. {escape(gate["reason"])}.</li>' for gate in gates)
    limits = "".join(f"<li>{escape(limit)}</li>" for limit in report["limitations"])
    runtime = report["runtime"]
    return f'''<!doctype html><html lang="nl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Experience Forge — echte agentvergelijking</title>
<style>*{{box-sizing:border-box}}body{{margin:0;background:#f3f4ef;color:#20342c;font:16px/1.55 system-ui,sans-serif}}main{{max-width:1120px;margin:auto;padding:30px 22px 65px}}header{{display:flex;justify-content:space-between;border-bottom:1px solid #d4dfd6;padding-bottom:16px;gap:15px}}header strong{{font-size:23px}}.badge{{font-size:12px;background:#e0ecdf;border-radius:20px;padding:6px 12px}}h1{{font-size:clamp(32px,5vw,56px);line-height:1.1;letter-spacing:-.045em;max-width:900px}}.intro{{font-size:19px;max-width:840px;color:#5b6e63}}.cards{{display:grid;grid-template-columns:repeat(3,1fr);gap:15px;margin:30px 0}}article{{background:#fff;border:1px solid #d4dfd6;border-radius:12px;padding:22px}}article strong{{font-size:42px}}article p{{margin:4px 0 15px}}dl{{display:grid;grid-template-columns:1fr auto;gap:10px;font-size:13px}}dd{{margin:0;text-align:right;font-weight:600}}dt{{color:#61766a}}h2{{font-size:25px;margin-top:35px}}.notice{{border-left:4px solid #547c5e;background:#e7eee4;padding:17px 20px}}.table{{overflow-x:auto;background:white;border:1px solid #d4dfd6;border-radius:10px}}table{{border-collapse:collapse;width:100%;font-size:13px}}td,th{{padding:12px;border-bottom:1px solid #edf0eb;text-align:left}}th{{background:#e7eee4;white-space:nowrap}}small{{display:block;font-size:11px;color:#6b786f;margin-top:4px}}.ok{{color:#276849}}.bad{{color:#a24532}}button{{font:inherit;font-size:13px;padding:10px 15px;background:#286247;color:white;border:0;border-radius:7px;cursor:pointer;margin-bottom:12px}}button:focus-visible{{outline:3px solid #b46d23;outline-offset:3px}}details{{padding:18px;border:1px solid #d4dfd6;border-radius:10px;margin-top:25px}}summary{{cursor:pointer;font-weight:650}}li{{margin:10px 0}}footer{{margin-top:30px;font-size:12px;color:#61766a;overflow-wrap:anywhere}}@media(max-width:720px){{.cards{{grid-template-columns:1fr}}main{{padding:22px 15px}}h1{{font-size:36px}}header{{align-items:flex-start}}}}</style></head><body><main>
<header><strong>Experience Forge / 0.2</strong><span class="badge">Echte lokale modelruns · €0 API-kosten</span></header>
<h1>Dezelfde agent.<br>Drie vormen van geheugen.</h1><p class="intro">Het model bestuurt tools, leert omrekenregels uit ervaringen en slaat nieuwe meetwaarden op. De beoordeling leest de werkelijke eindtoestand. Een overtuigend antwoord alleen telt niet als succes.</p>
<div class="notice">Dit is een kleine pilot met {report["protocol"]["trials"]} datasets en één taakfamilie. De cijfers tonen de uitkomst van deze runs, ook wanneer een variant geen voordeel heeft. Er is geen bewijs van algemene intelligentie of brede statistische superioriteit.</div>
<div class="cards">{cards}</div>
<h2>Wat gelijk is gehouden</h2><p>Hetzelfde model, dezelfde trainingsvoorbeelden en door het model voorgestelde regels, dezelfde tools en dezelfde eindtaken. Elke taak heeft maximaal {report["protocol"]["max_calls_per_rollout"]} modelaanroepen en {report["protocol"]["max_tools_per_rollout"]} toolacties. De volgorde roteert om de invloed van opwarming en caching te beperken. Alleen de selectie van herinnerde regels verschilt.</p>
<p>Werkelijk verbruik kan verschillen. Gemeenschappelijke training en voorstellen zijn één keer uitgevoerd en worden aan elke variant gelijk toegerekend: {report["shared_learning"]["model_calls"]} modelaanroepen, {report["shared_learning"]["input_tokens"]} invoertokens en {report["shared_learning"]["output_tokens"]} uitvoertokens. Deze kosten staan apart van de eindtestcijfers hierboven. De getoetste variant heeft daarnaast deterministische kwalificatiekosten; daarvoor worden geen modelaanroepen gedaan.</p>
<h2>Door het model afgeleide vaardigheden</h2><p>De functionele vorm is vooraf gegeven. De coëfficiënten worden door het model uit de ervaringen afgeleid; ze worden niet uit de verborgen connectorconfiguratie aan het model meegegeven.</p><ul>{gate_rows}</ul>
<h2>Alle eindtaken, naast elkaar</h2><button type="button" id="filter" aria-pressed="false">Toon alleen verschillen in succes</button><div class="table"><table><thead><tr><th>Trial</th><th>Taak</th><th>Geen geheugen</th><th>Ongetoetst geheugen</th><th>Getoetst geheugen</th></tr></thead><tbody>{rows}</tbody></table></div>
<details open><summary>Beperkingen en bewijs</summary><ul>{limits}</ul><p>Bewijs: protocol.json, fixtures.json, model-calls.jsonl, rollouts.jsonl, proposals.jsonl, gates.jsonl, memory.sqlite3, report.json en manifest.json. Opgeslagen modeluitvoer kan zonder nieuw model opnieuw door de echte toolomgeving worden afgespeeld.</p></details>
<footer>Model: {escape(runtime["model"]["name"])} · Ollama {escape(runtime["runtime"]["version"])}<br>Model SHA-256: {escape(runtime["model"]["digest"])}<br>Betaalde API-aanroepen: {report["paid_api_calls"]} · Externe netwerkverzoeken door het experiment: {report["remote_network_requests"]}</footer>
</main><script>const button=document.getElementById('filter');button.addEventListener('click',()=>{{const filtered=button.getAttribute('aria-pressed')!=='true';button.setAttribute('aria-pressed',String(filtered));button.textContent=filtered?'Toon alle taken':'Toon alleen verschillen in succes';document.querySelectorAll('tbody tr').forEach(row=>row.hidden=filtered&&row.dataset.different!=='true');}});</script></body></html>'''
